mapper.select:
SELECT outbox_id, aggregate_type, aggregate_id, event_type, payload_json, idempotency_key
FROM ai_outbox_event WHERE status='PENDING' AND available_time <= NOW()
ORDER BY outbox_id LIMIT #{limit}

mapper.update:
UPDATE ai_run SET status=#{status}, update_time=NOW(), finished_time=IF(#{status} IN ('SUCCEEDED','FAILED','CANCELLED','TIMED_OUT'),NOW(),finished_time)
WHERE run_id=#{runId} AND status=#{expectedStatus} AND worker_id=#{workerId}
  AND lease_until > NOW() AND status NOT IN ('SUCCEEDED','FAILED','CANCELLED','TIMED_OUT')

mapper.select:
SELECT event_id,run_id,sequence_no,event_type,event_json,idempotency_key,create_time
FROM ai_run_event WHERE run_id=#{runId} AND sequence_no > #{sequence}
ORDER BY sequence_no LIMIT #{limit}

SELECT conversation_id, agent_id, user_id, title, status, create_time, update_time FROM ai_conversation WHERE (user_id=#{userId} OR #{userId}=1)
AND title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY update_time DESC LIMIT #{offset},#{limit}
